#!/usr/bin/env node
// Compatibility entry point. Final exports are generated by the reusable renderer.
const renderer = require('./render-og.cjs');
renderer.render(renderer.parseArgs(process.argv.slice(2))).then(result => console.log(JSON.stringify(result, null, 2))).catch(error => { console.error(error.message); process.exitCode = 1; });
